const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('console', msg => console.log('CONSOLE:', msg.text()));
  page.on('pageerror', err => console.log('PAGEERROR:', err.message));
  await page.goto('http://localhost:8934/index.html', { waitUntil: 'networkidle' });

  // Select Ultra Mode format
  await page.getByRole('button', { name: /Ultra Mode/ }).click();
  await page.screenshot({ path: '/tmp/pwtest/01-setup.png', fullPage: true });

  // Scroll to find "Spin" button / start draft button
  const html = await page.content();
  require('fs').writeFileSync('/tmp/pwtest/setup.html', html);

  console.log('Setup screen text near format toggle captured.');
  await browser.close();
})();
